CREATE TABLE IF NOT EXISTS markets(coin TEXT PRIMARY KEY, dex TEXT NOT NULL, underlying_venue TEXT, underlying_symbol TEXT, asset_class TEXT, calendar_id TEXT, mapped BOOLEAN DEFAULT TRUE, updated_at BIGINT);
CREATE TABLE IF NOT EXISTS asset_ctx_snapshots(coin TEXT NOT NULL, ts BIGINT NOT NULL, oracle_px DOUBLE PRECISION, mark_px DOUBLE PRECISION, mid_px DOUBLE PRECISION, funding DOUBLE PRECISION, open_interest DOUBLE PRECISION, premium DOUBLE PRECISION, impact_bid DOUBLE PRECISION, impact_ask DOUBLE PRECISION, PRIMARY KEY(coin, ts));
CREATE TABLE IF NOT EXISTS ref_quotes(coin TEXT NOT NULL, source TEXT NOT NULL, ts BIGINT NOT NULL, price DOUBLE PRECISION NOT NULL, session TEXT, confidence DOUBLE PRECISION, PRIMARY KEY(coin, source, ts));
CREATE TABLE IF NOT EXISTS metric_snapshots(coin TEXT NOT NULL, ts BIGINT NOT NULL, divergence_bps DOUBLE PRECISION, mark_premium_bps DOUBLE PRECISION, cross_dex_spread_bps DOUBLE PRECISION, staleness_ms DOUBLE PRECISION, stale_p50_ms DOUBLE PRECISION, stale_p95_ms DOUBLE PRECISION, depth_bid_1pct DOUBLE PRECISION, depth_ask_1pct DOUBLE PRECISION, flag TEXT, session_state TEXT, PRIMARY KEY(coin, ts));
CREATE TABLE IF NOT EXISTS archive_accounts(address TEXT PRIMARY KEY, registered_at BIGINT, last_fill_ts BIGINT, last_funding_ts BIGINT, last_ledger_ts BIGINT, status TEXT);
CREATE TABLE IF NOT EXISTS fills(address TEXT NOT NULL, tid BIGINT NOT NULL, coin TEXT, px DOUBLE PRECISION, sz DOUBLE PRECISION, side TEXT, dir TEXT, time BIGINT, closed_pnl DOUBLE PRECISION, fee DOUBLE PRECISION, fee_token TEXT, builder_fee DOUBLE PRECISION, crossed BOOLEAN, hash TEXT, oid BIGINT, liquidation JSONB, raw JSONB, PRIMARY KEY(address, tid));
CREATE TABLE IF NOT EXISTS fundings(address TEXT NOT NULL, time BIGINT NOT NULL, coin TEXT NOT NULL, usdc DOUBLE PRECISION, szi DOUBLE PRECISION, funding_rate DOUBLE PRECISION, raw JSONB, PRIMARY KEY(address, time, coin));
CREATE TABLE IF NOT EXISTS ledger_updates(address TEXT NOT NULL, time BIGINT NOT NULL, hash TEXT NOT NULL, kind TEXT, delta JSONB, PRIMARY KEY(address, hash, time));
CREATE TABLE IF NOT EXISTS alert_subscriptions(id TEXT PRIMARY KEY, telegram_chat_id TEXT, kind TEXT, coin TEXT, address TEXT, params JSONB);
CREATE TABLE IF NOT EXISTS incident_drafts(id TEXT PRIMARY KEY, coin TEXT, started_at BIGINT, peak_divergence_bps DOUBLE PRECISION, text TEXT, posted BOOLEAN DEFAULT FALSE);
